<template>
  <div class="page-container" :class="{'has-workspace':!!workspace}" data-testid="collaboration-page">
    <div v-if="!workspace" class="page-heading"><div><div class="page-kicker">WATCHTOWER TEAM</div><h1>{{ t('team.title') }}</h1><p :title="t('team.description')" class="page-description">{{ t('team.description') }}</p></div><a-button :loading="loading" @click="refreshAll">{{ t('control.refresh') }}</a-button></div>
    <a-alert v-if="error" :message="error" type="error" class="page-alert" show-icon closable @close="error=''" />
<div v-if="!workspace && state.identity?.crypto_fingerprint" class="team-own-fingerprint"><span>{{ t('teamCache.myFingerprint') }}</span><a-typography-paragraph :copyable="{text:state.identity.crypto_fingerprint}">{{ state.identity.crypto_fingerprint }}</a-typography-paragraph></div>
    <a-card v-if="!workspace" class="page-card" :title="t('team.groups')" data-testid="team-groups-card">
      <template #extra><a-space wrap><a-button :disabled="busy" @click="showDialog('join')" data-testid="open-group-join">{{ t('team.join') }}</a-button><a-button type="primary" :disabled="busy" @click="showDialog('create')" data-testid="open-group-create">{{ t('team.create') }}</a-button></a-space></template>
      <a-empty v-if="!groups.length" :description="t('team.empty')" />
      <div v-for="group in groups" :key="group._id" class="team-row"><div><strong>{{ group.name }}</strong><a-badge v-if="notifications.unread_groups[group.group_id || group._id]" :count="notifications.unread_groups[group.group_id || group._id]" class="team-unread" data-testid="group-unread" /><a-tooltip v-if="!group.group_id && group.pending_count>0" :title="t('teamKeys.pending',{count:group.pending_count})" :overlay-style="{position:'fixed',pointerEvents:'none'}"><span class="team-bell" role="status" :aria-label="t('teamKeys.pending',{count:group.pending_count})" data-testid="group-pending-bell" :data-group-id="group._id"><BellOutlined aria-hidden="true" />{{ group.pending_count }}</span></a-tooltip><div class="team-muted">{{ sourceLabel(group.source) }} · {{ group.group_id || group._id }}</div><div v-if="group.peer_error" class="team-muted peer-offline" data-testid="peer-offline"><a-tag color="gold">{{ t('invitationLink.peerUnavailable') }}</a-tag>{{ group.peer_error }}<span>{{ t('invitationLink.retryAfter') }} {{ date(group.peer_retry_at) }}</span></div></div><a-space wrap><a-tag>{{ group.state?t('control.states.'+group.state):t('team.host') }}</a-tag><a-button v-if="group.group_id" :disabled="busy" @click="refreshLink(group._id)">{{ t('control.refresh') }}</a-button><a-button :disabled="busy || !!group.state && group.state!=='approved'" @click="open(group.group_id || group._id)" data-testid="open-group">{{ t('team.open') }}</a-button><a-button danger :disabled="busy" @click="deleteTarget=group;deleteError=''" data-testid="delete-group">{{ t('control.delete') }}</a-button></a-space></div>
    </a-card>
    <template v-if="workspace">
      <a-card class="page-card workspace-card" data-testid="group-workspace">
        <template #title><div class="workspace-caption"><span :title="workspace.group.name+' · '+t('team.workspace')">{{ workspace.group.name }} · {{ t('team.workspace') }}</span></div></template>
        <template #extra><a-space wrap><a-button :disabled="busy" @click="leaveWorkspace" data-testid="workspace-back"><ArrowLeftOutlined />{{ t('teamWorkspace.back') }}</a-button><a-button :disabled="busy" @click="cacheView='cache';cacheGroup=workspace.group._id;cacheOpen=true" data-testid="open-cache-settings">{{ t('teamCache.title') }}</a-button><a-button v-if="host" :disabled="busy" @click="cacheView='nodes';cacheGroup=workspace.group._id;cacheOpen=true" data-testid="open-node-settings">{{ t('teamCache.nodes') }}</a-button><a-button :disabled="busy" @click="showDialog('members')" data-testid="open-group-members">{{ t('team.members') }}</a-button><a-button v-if="host" :disabled="busy" @click="showDialog('applications')" data-testid="open-group-applications">{{ t('teamWorkspace.applications') }}<a-badge v-if="pendingCount" :count="pendingCount" style="margin-left:8px" /></a-button><a-button v-if="!host" :disabled="busy" @click="showService" data-testid="open-service-offer">{{ t('teamService.offer') }}</a-button><a-button v-if="host && hasPerm('collaboration:write')" :disabled="busy" @click="openKeys" data-testid="open-group-invite">{{ t('teamKeys.title') }}</a-button></a-space></template>
        <div class="workspace-service-status" data-testid="workspace-service-status" role="status"><span>{{ t('teamService.manager') }}：<strong>{{ managerName }}</strong></span><span>{{ t('teamService.current') }}：<strong>{{ workspace.offline?t('teamService.routes.offline'):serviceName }}</strong></span><span>{{ t('teamService.route') }}：{{ t('teamService.routes.'+(workspace.service_route || 'unknown')) }}</span></div>
        <a-alert v-if="workspace.host_offline && !workspace.offline" :message="t('teamService.failoverNote')" type="info" show-icon class="room-alert" />
        <a-alert v-if="workspace.offline" :message="t('teamCache.hostOffline')" type="warning" show-icon class="room-alert" /><div class="room-layout"><nav class="room-nav" :aria-label="t('team.workspace')" data-testid="room-navigation">
          <button :class="{active:!peerId}" @click="chooseRoom('')" data-testid="room-group"><strong>{{ t('team.groupRoom') }}<a-badge v-if="roomUnread('group')" :count="roomUnread('group')" data-testid="group-room-unread" /></strong><span>{{ t('team.groupScope') }}</span></button><div class="room-nav-label">{{ t('team.directRoom') }}</div><div v-if="!contacts.length" class="team-muted room-empty">{{ t('team.noContacts') }}</div>
          <button v-for="member in contacts" :key="member._id" :class="{active:peerId===member._id}" @click="chooseRoom(member._id)" data-testid="room-direct" :data-member-id="member._id"><strong>{{ member.name }}<a-badge v-if="roomUnread(member._id)" :count="roomUnread(member._id)" data-testid="direct-room-unread" /></strong><span>{{ sourceLabel(member.source) }}</span><span v-if="member.state!=='approved'">{{ t('control.states.'+member.state) }}</span></button>
        </nav><section class="room-chat" :aria-label="roomTitle">
          <div class="room-heading"><div><strong data-testid="room-title">{{ roomTitle }}</strong><p class="team-muted">{{ t(peerId?'team.directScope':'team.groupScope') }}</p></div><a-button :disabled="busy || !canSend" @click="openShare" data-testid="open-share-package">{{ t('team.share') }}</a-button></div>
          <a-alert v-if="roomError" :message="roomError" type="warning" show-icon class="room-alert" /><a-alert v-if="gap" :message="t('team.historyGap')" type="info" show-icon closable @close="gap=false" class="room-alert" />
          <div ref="timeline" class="room-timeline" @scroll="checkFollow" :aria-busy="roomLoading" data-testid="room-timeline"><div class="older-control"><a-button v-if="hasOlder" size="small" :loading="olderLoading" @click="older" data-testid="room-older">{{ t('team.older') }}</a-button><a-spin v-if="roomLoading" size="small" /></div><div v-if="!entries.length && !roomLoading" class="room-empty team-muted">{{ t('team.roomEmpty') }}</div>
            <article v-for="entry in entries" :key="entry._id" class="room-entry" :class="{mine:entry.sender===workspace.self_member_id}" :data-entry-id="entry._id" data-testid="room-entry"><div class="entry-meta"><strong>{{ memberName(entry.sender) }}</strong><time>{{ date(entry.created_at) }}</time></div><div class="team-muted entry-source">{{ sourceLabel(entry.source) }}</div><div v-if="entry.kind==='message'" class="message-bubble" data-testid="room-message">{{ entry.text }}</div><div v-else class="package-bubble data-card" role="button" tabindex="0" :aria-label="entry.title" @click="preview(entry._id)" @keydown.enter.prevent="preview(entry._id)" @keydown.space.prevent="preview(entry._id)" data-testid="room-package"><div class="data-card-top"><span class="data-card-icon">{{ entry.kind==='finding'?'◇':entry.kind==='session'?'◉':entry.kind==='report'?'▤':'↥' }}</span><a-tag>{{ t('team.kinds.'+entry.kind) }}</a-tag></div><strong>{{ entry.kind==='file'?entry.summary?.file_name || entry.title:entry.title }}</strong><div class="team-muted">{{ (Number(entry.kind==='file'?entry.summary?.file_bytes || 0:entry.bytes || 0)/1024).toFixed(1) }} KiB · {{ t('team.preview') }}</div><a-button v-if="entry.kind==='file'" size="small" :loading="downloading===entry._id" :disabled="busy || !!downloading" @click.stop="downloadAttachment(entry)" data-testid="download-workspace-file">{{ t('teamFiles.download') }}</a-button></div><div v-if="entry.delivery_state" class="team-muted entry-delivery" data-testid="entry-delivery">{{ t('teamCache.states.'+entry.delivery_state) }}</div><div v-else-if="entry.kind!=='message'" class="team-muted entry-delivery">{{ t(entry.received?'teamCache.fileReceived':'teamCache.captionOnly') }}</div></article>
          </div><a-button v-if="newMessages" class="new-messages" size="small" @click="jumpLatest">{{ t('team.newMessages',{count:newMessages}) }}</a-button>
          <form class="room-composer" @submit.prevent="sendMessage">
            <a-textarea v-model:value="draft" :maxlength="2000" :auto-size="{minRows:2,maxRows:5}" :disabled="!canSend || sending" :placeholder="t(canSend?'team.messagePlaceholder':'team.peerUnavailable')" data-testid="room-message-input" />
            <div v-if="attachments.length" class="composer-files" data-testid="workspace-file-drafts"><div v-for="item in attachments" :key="item.nonce" class="composer-file"><span>{{ item.file.name }} · {{ (item.file.size/1024).toFixed(1) }} KiB</span><a-button size="small" type="text" :disabled="busy" @click="removeAttachment(item.nonce)" :aria-label="t('teamFiles.remove')">×</a-button></div></div>
            <div class="composer-actions"><div class="composer-tools"><a-upload :multiple="true" :show-upload-list="false" :before-upload="selectAttachment" :disabled="busy || !canSend || workspace?.group.crypto_format!==1"><a-button :disabled="busy || !canSend || workspace?.group.crypto_format!==1" :title="t(workspace?.group.crypto_format===1?'teamFiles.limit':'teamFiles.needCrypto')" data-testid="upload-workspace-file">↥ {{ t('teamFiles.upload') }}</a-button></a-upload><span class="team-muted">{{ draft.length }} / 2000</span></div><a-button html-type="submit" type="primary" :loading="sending" :disabled="working || !canSend || (!draft.trim() && !attachments.length)" data-testid="room-send">{{ t('team.sendMessage') }}</a-button></div>
            <div v-if="fileProgress" class="team-muted" role="status">{{ fileProgress }}</div>
          </form>
        </section></div>
      </a-card>
      <a-card v-if="legacyItems.length" class="page-card" :title="t('team.legacyShared')" data-testid="legacy-shared"><p class="team-muted">{{ t('team.legacyNote') }}</p><a-table :data-source="legacyItems" :columns="itemColumns" row-key="_id" :scroll="{x:760}" :pagination="{pageSize:8}"><template #bodyCell="{column,record}"><template v-if="column.key==='kind'">{{ t('team.kinds.'+record.kind) }}</template><template v-else-if="column.key==='source'">{{ sourceLabel(record.source) }}</template><template v-else-if="column.key==='actions'"><a-space><a-button size="small" :disabled="busy" @click="preview(record._id)">{{ t('team.preview') }}</a-button><a-button v-if="record.kind==='session'" size="small" :disabled="busy" @click="restoreItem=record;provider='';restoreError=''">{{ t('team.restore') }}</a-button></a-space></template></template></a-table></a-card>
    </template>
    <div v-if="!workspace" class="team-guides" data-testid="team-guides"><a-card class="page-card" :title="t('team.joinGuide')"><p>{{ t('team.joinNote') }}</p><p class="team-muted">{{ t('team.keyNote') }}</p></a-card><a-card class="page-card" :title="t('team.handoffGuide')"><p>{{ t('team.sessionNote') }}</p><p class="team-muted">{{ t('team.restoreNote') }}</p></a-card></div>
    <CollaborationCache :view="cacheView" :open="cacheOpen && !!cacheGroup" :group-id="cacheGroup" :host="!!host" @close="cacheOpen=false" @saved="refreshAll" />
    <a-modal :open="!!dialog" :title="dialogTitle" :footer="null" :width="['members','applications','keys'].includes(dialog)?920:620" :mask-closable="!working" :keyboard="!working" :closable="!working" :destroy-on-close="true" @cancel="closeDialog" data-testid="team-action-dialog">
      <a-alert v-if="dialogError" :message="dialogError" type="error" show-icon class="page-alert" data-testid="team-dialog-error" />
      <a-form v-if="dialog==='create'" layout="vertical" @submit.prevent="create"><a-form-item :label="t('control.name')" required><a-input v-model:value="name" :maxlength="80" :disabled="working" data-testid="group-name" /></a-form-item><a-form-item :label="t('invitationLink.reachableAddress')" required><a-input v-model:value="publicTarget" :disabled="working" placeholder="192.168.1.10:5555" data-testid="group-public-target" /><p class="team-muted">{{ t('invitationLink.reachableNote') }}</p></a-form-item><a-form-item :label="t('teamKeys.mode')"><a-radio-group v-model:value="createSingle" :disabled="working" data-testid="createSingle"><a-radio :value="true">{{ t('teamKeys.once') }}</a-radio><a-radio :value="false">{{ t('teamKeys.reusable') }}</a-radio></a-radio-group></a-form-item><a-form-item><a-checkbox v-model:checked="longKey" :disabled="working" data-testid="group-long-key">{{ t('invitationLink.longKey') }}</a-checkbox></a-form-item><a-form-item v-if="!longKey" :label="t('team.keyMinutes')" required><a-input-number v-model:value="minutes" :min="1" :max="129600" :disabled="working" class="full" data-testid="group-expiry" /></a-form-item><a-form-item :label="t('invitationLink.memberLimit')" required><a-input-number v-model:value="maxMembers" :min="1" :max="100" :disabled="working" class="full" data-testid="group-member-limit" /></a-form-item><a-form-item><a-checkbox v-model:checked="approvalRequired" :disabled="working" data-testid="group-approval-required">{{ t('invitationLink.requireApproval') }}</a-checkbox></a-form-item><a-form-item :label="t('team.memberMinutes')" required><a-input-number v-model:value="memberMinutes" :min="5" :max="525600" :disabled="working" class="full" data-testid="member-expiry" /></a-form-item><a-button type="primary" :loading="working" html-type="submit" data-testid="create-group">{{ t('team.create') }}</a-button></a-form>
      <a-form v-else-if="dialog==='join'" layout="vertical" @submit.prevent="join"><a-form-item :label="t('invitationLink.pasteLink')"><a-input-password v-model:value="invitationInput" :disabled="working" autocomplete="off" :maxlength="4096" @change="fillInvitation" data-testid="group-invitation-link" /><p class="team-muted">{{ t('invitationLink.pasteNote') }}</p></a-form-item><a-form-item :label="t('team.coordinator')" required><a-input v-model:value="target" :disabled="working" placeholder="192.168.1.10:5555" data-testid="group-target" /></a-form-item><a-form-item :label="t('team.inviteKey')" required><a-input-password v-model:value="inviteKey" :disabled="working" autocomplete="off" data-testid="group-key" /></a-form-item><p class="team-muted">{{ t('team.joinNote') }}</p><a-button type="primary" :loading="working" html-type="submit" data-testid="join-group">{{ t('team.apply') }}</a-button></a-form>
      <a-form v-else-if="dialog==='invite'" layout="vertical" @submit.prevent="renewInvite"><a-form-item :label="t('invitationLink.reachableAddress')" required><a-input v-model:value="publicTarget" :disabled="working" data-testid="invite-public-target" /></a-form-item><a-form-item :label="t('teamKeys.name')"><a-input v-model:value="inviteName" :maxlength="80" :disabled="working" data-testid="invite-name" /></a-form-item><a-form-item :label="t('teamKeys.mode')"><a-radio-group v-model:value="inviteSingle" :disabled="working" data-testid="inviteSingle"><a-radio :value="true">{{ t('teamKeys.once') }}</a-radio><a-radio :value="false">{{ t('teamKeys.reusable') }}</a-radio></a-radio-group></a-form-item><a-form-item><a-checkbox v-model:checked="inviteLong" :disabled="working">{{ t('invitationLink.longKey') }}</a-checkbox></a-form-item><a-form-item :label="t('invitationLink.memberLimit')" required><a-input-number v-model:value="maxMembers" :min="1" :max="100" :disabled="working" class="full" data-testid="group-member-limit" /></a-form-item><a-form-item><a-checkbox v-model:checked="approvalRequired" :disabled="working" data-testid="group-approval-required">{{ t('invitationLink.requireApproval') }}</a-checkbox></a-form-item><a-form-item v-if="!inviteLong" :label="t('team.keyMinutes')" required><a-input-number v-model:value="inviteMinutes" :min="1" :max="129600" :disabled="working" class="full" data-testid="invite-expiry" /></a-form-item><p class="team-muted">{{ t('team.keyNote') }}</p><a-button type="primary" :loading="working" html-type="submit" data-testid="renew-group-invite">{{ t('team.newKey') }}</a-button></a-form>
      <a-form v-else-if="dialog==='share'" layout="vertical" @submit.prevent="share"><p>{{ t('team.destination') }}: <strong>{{ roomTitle }}</strong></p><p class="team-muted">{{ t(peerId?'team.directScope':'team.groupScope') }}</p><a-form-item :label="t('team.kind')"><a-select v-model:value="kind" :options="kindOptions" :disabled="working" @change="objectId=''" data-testid="share-kind" /></a-form-item><a-form-item :label="t('team.object')" required><a-button block :disabled="working" @click="openCandidates" data-testid="share-object">{{ selectedObject?.title || t('repair128.selectData') }}</a-button></a-form-item><a-alert v-if="kind==='session'" type="info" :message="t('team.sessionNote')" show-icon class="page-alert" /><a-button type="primary" :loading="working" html-type="submit" data-testid="share-package">{{ t('team.send') }}</a-button></a-form>
      <div v-else-if="dialog==='keys'" data-testid="group-key-manager">
        <div class="key-manager-actions"><p class="team-muted">{{ t('teamKeys.coexist') }}</p><a-button type="primary" @click="showDialog('invite')" :disabled="working" data-testid="add-invitation-key">{{ t('teamKeys.add') }}</a-button></div>
        <a-table :data-source="invitationKeys" :columns="keyColumns" :loading="keysLoading" row-key="_id" :pagination="{pageSize:6}" :scroll="{x:720}">
          <template #bodyCell="{column,record}">
            <template v-if="column.key==='name'">{{ record.name || t(record.primary?'teamKeys.primary':'teamKeys.additional') }}</template>
            <template v-else-if="column.key==='mode'"><a-tag>{{ t(record.single_use?'teamKeys.once':'teamKeys.reusable') }}</a-tag></template>
            <template v-else-if="column.key==='expiry'">{{ record.expires_at==null?t('invitationLink.longKey'):date(record.expires_at) }}</template>
            <template v-else-if="column.key==='state'"><a-tag :color="record.state==='active'?'success':'default'">{{ t('teamKeys.states.'+record.state) }}</a-tag></template>
            <template v-else-if="column.key==='actions'"><a-space><a-button size="small" :disabled="working || record.state!=='active'" @click="viewKey(record)" data-testid="view-invitation-key">{{ t('teamKeys.viewCopy') }}</a-button><a-popconfirm v-if="record.state==='active'" :title="t('teamKeys.revokeConfirm')" @confirm="revokeKey(record)"><a-button size="small" danger :disabled="working" data-testid="revoke-invitation-key">{{ t('teamKeys.revoke') }}</a-button></a-popconfirm></a-space></template>
          </template>
        </a-table>
      </div>

      <a-table v-else-if="dialog==='members'" :data-source="workspace?.members || []" :columns="memberColumns" row-key="_id" :pagination="false" :scroll="{x:760}"><template #bodyCell="{column,record}"><template v-if="column.key==='service'">{{ t(record.host?'team.host':record.cohost?'teamService.cohost':'teamService.member') }}<span v-if="record.service_state"> · {{ t('teamService.states.'+record.service_state) }}</span><div v-if="record.service_error" class="team-muted" role="status" data-testid="service-preparation-error">{{ record.service_error }}</div></template><template v-else-if="column.key==='source'">{{ sourceLabel(record.source) }}</template><template v-else-if="column.key==='state'"><a-tag>{{ t('control.states.'+record.state) }}</a-tag></template><template v-else-if="column.key==='actions'"><a-space v-if="host" wrap><a-tooltip v-if="!record.host && record.state==='approved'" :title="!record.cohost && !record.service_offered?t('revision24.offerFirst'):''"><span><a-button size="small" :disabled="working || (!record.cohost && !record.service_offered)" @click="assignService(record._id,!record.cohost)" data-testid="assign-cohost">{{ t(record.cohost?'revision24.revokeCohost':'revision24.assignCohost') }}</a-button></span></a-tooltip><a-button size="small" :disabled="working" @click="showRename(record._id)" data-testid="rename-member">{{ t('teamWorkspace.rename') }}</a-button><a-button v-if="record.state==='pending'" type="primary" size="small" :disabled="working" @click="decide(record._id,true)" data-testid="approve-member">{{ t('team.approve') }}</a-button><a-button v-if="record.state==='pending'" danger size="small" :disabled="working" @click="decide(record._id,false)">{{ t('control.reject') }}</a-button><a-button v-if="!record.host && record.state==='approved'" danger size="small" :disabled="working" @click="remove(record._id)">{{ t('team.remove') }}</a-button></a-space><a-button v-else-if="record._id===workspace.self_member_id" size="small" :disabled="working" @click="showRename(record._id)" data-testid="rename-own-member">{{ t('teamWorkspace.requestRename') }}</a-button></template></template></a-table>

      <template v-else-if="dialog==='applications'">
        <h3>{{ t('teamWorkspace.joinApplications') }}</h3>
        <a-table :data-source="workspace?.applications || []" :columns="memberColumns" row-key="_id" :pagination="false" :scroll="{x:660}" data-testid="join-applications"><template #bodyCell="{column,record}"><template v-if="column.key==='source'">{{ sourceLabel(record.source) }}</template><template v-else-if="column.key==='state'">{{ t('control.states.'+record.state) }}</template><template v-else-if="column.key==='actions'"><a-space><a-button type="primary" size="small" :disabled="working" @click="decide(record._id,true)" data-testid="approve-member">{{ t('team.approve') }}</a-button><a-button danger size="small" :disabled="working" @click="decide(record._id,false)">{{ t('control.reject') }}</a-button></a-space></template></template></a-table>
        <h3>{{ t('teamWorkspace.renameApplications') }}</h3>
        <a-table :data-source="workspace?.rename_requests || []" :columns="renameColumns" row-key="_id" :pagination="false" :scroll="{x:600}" data-testid="rename-applications"><template #bodyCell="{column,record}"><template v-if="column.key==='actions'"><a-space><a-button type="primary" size="small" :disabled="working" @click="decideRename(record._id,true)" data-testid="approve-rename">{{ t('team.approve') }}</a-button><a-button danger size="small" :disabled="working" @click="decideRename(record._id,false)">{{ t('control.reject') }}</a-button></a-space></template></template></a-table>
      </template>
