let waitingLink='',pollOffset=0
const target=ref(''),inviteKey=ref(''),newKey=ref(''),kind=ref('finding'),objectId=ref(''),previewData=ref<any>(null),restoreItem=ref<any>(null),provider=ref('')
const peerId=ref(''),entries=ref<any[]>([]),draft=ref(''),roomError=ref(''),roomLoading=ref(false),olderLoading=ref(false),gap=ref(false),hasOlder=ref(false),canSend=ref(true),newMessages=ref(0),timeline=ref<HTMLElement|null>(null)
const groups=computed(()=>[...state.value.groups,...state.value.links]),host=computed(()=>workspace.value && state.value.groups.some((g:any)=>g._id===workspace.value.group._id))
const contacts=computed(()=>workspace.value?.contacts || []),legacyItems=computed(()=>(workspace.value?.items || []).filter((i:any)=>(i.audience || 'legacy')==='legacy'))
const pendingCount=computed(()=>Number(workspace.value?.group.pending_count || 0))
