const keyColumns=computed(()=>[{title:t('control.name'),key:'name'},{title:t('teamKeys.mode'),key:'mode'},{title:t('control.expiry'),key:'expiry'},{title:t('control.status'),key:'state'},{title:t('control.actions'),key:'actions',width:210}])
