const renameColumns=computed(()=>[{title:t('control.name'),dataIndex:'name'},{title:t('teamWorkspace.requestedName'),dataIndex:'requested_name'},{title:t('control.actions'),key:'actions'}])
const roomUnread=(room:string)=>notifications.value.unread_rooms[workspace.value?.group._id]?.[room] || 0
const itemColumns=computed(()=>[{title:t('control.name'),dataIndex:'title'},{title:t('team.kind'),key:'kind'},{title:t('team.source'),key:'source'},{title:t('control.actions'),key:'actions'}])
const sourceLabel=(s:any)=>s?(s.product==='win'?'Windows':'Web')+' · '+(s.name || '')+' · '+(s.version || '')+' · '+String(s.instance_id || '').slice(0,8):'—'
