const attachments=ref<AttachmentDraft[]>([]),downloading=ref(''),fileProgress=ref('')
const attachmentDrafts=shallowReactive(new Map<string,AttachmentDraft[]>())
const {markSaved:markAttachmentBaseline}=useUnsavedGuard(()=>{attachments.value;return JSON.stringify([...attachmentDrafts].map(([key,files])=>[key,files.map(item=>item.nonce)]))},{get content(){return t('teamFiles.unsaved')}})
function saveAttachmentDrafts(key=roomKey()){if(key){if(attachments.value.length)attachmentDrafts.set(key,attachments.value);else attachmentDrafts.delete(key)}}
function selectAttachment(file:File){
 if(busy.value || !canSend.value)return false
 if(file.size>20*1024*1024-65536 || attachments.value.reduce((total,item)=>total+item.file.size,0)+file.size>20*1024*1024-65536 || attachments.value.length>=5){roomError.value=t('teamFiles.limit');return false}
 if(attachments.value.some(item=>item.file.name===file.name && item.file.size===file.size && item.file.lastModified===file.lastModified))return false
 roomError.value=''
 attachments.value=[...attachments.value,{file,nonce:sendNonce()}];saveAttachmentDrafts();return false
}
function removeAttachment(nonce:string){if(busy.value)return;roomError.value='';attachments.value=attachments.value.filter(item=>item.nonce!==nonce);saveAttachmentDrafts()}
async function uploadAttachment(gid:string,args:{audience:string;peer_id:string},item:AttachmentDraft){
 const form=new FormData();form.append('file',item.file);form.append('nonce',item.nonce);form.append('audience',args.audience);form.append('peer_id',args.peer_id)
 const response=await fetch(root+'/groups/'+gid+'/attachments',{method:'POST',headers:{Token:getToken()},body:form});const result=await response.json().catch(()=>({message:t('teamFiles.failed')}))
 if(!response.ok || result.code!==200)throw new Error(result.message || t('teamFiles.failed'))
 return result.data
}
async function downloadAttachment(entry:any){
 if(!workspace.value || downloading.value || busy.value)return
 const e=epoch,gid=workspace.value.group._id;downloading.value=entry._id;roomError.value=''
 try{
  const response=await fetch(root+'/groups/'+gid+'/attachments/'+entry._id+'/download',{headers:{Token:getToken()}})
  if(!response.ok || response.headers.get('content-type')?.includes('application/json')){const result=await response.json().catch(()=>({}));throw new Error(result.message || t('teamFiles.failed'))}
  const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=entry.summary?.file_name || entry.title || 'attachment';link.click();setTimeout(()=>URL.revokeObjectURL(url),5000)
 }catch(exc){if(e===epoch && !disposed)roomError.value=localizedError(exc)}finally{downloading.value=''}
}

const roomKey=()=>workspace.value?.group._id+':'+peerId.value
const roomArgs=()=>({audience:peerId.value?'direct':'group',peer_id:peerId.value})
const sendNonce=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),value=>value.toString(16).padStart(2,'0')).join('')
const managerName=computed(()=>workspace.value?.members?.find((m:any)=>m.host)?.name || workspace.value?.group?.name || '')
const serviceName=computed(()=>workspace.value?.members?.find((m:any)=>m._id===workspace.value?.service_member_id)?.name || managerName.value)
function showService(){const own=workspace.value?.self_service || {};serviceEnabled.value=own.enabled===true;serviceAddress.value=own.url || '';showDialog('service')}
function showDialog(value:string){if(busy.value)return;dialogError.value='';if(value==='invite' && workspace.value){publicTarget.value=workspace.value.group.public_target || '';inviteLong.value=true;inviteSingle.value=false;inviteName.value='';maxMembers.value=workspace.value.group.max_members || 50;approvalRequired.value=workspace.value.group.approval_required !== false}dialog.value=value}
function closeDialog(){if(working.value)return;dialog.value='';dialogError.value='';inviteKey.value='';invitationInput.value='';nodeDescriptor.value=undefined}
function fillInvitation(){if(!invitationInput.value.trim())return;try{const parsed=parseInvitationLink(invitationInput.value,'group');target.value=parsed.target;inviteKey.value=parsed.key;nodeDescriptor.value=parsed.node_descriptor;dialogError.value=''}catch(e){dialogError.value=localizedError(e)}}
const readControllers=new Set<AbortController>(),readPending=new Set<string>(),readPositions=new Map<string,number>()
async function boundedGet<T>(path:string,silent=false):Promise<T>{
 const controller=new AbortController();readControllers.add(controller);const timeout=setTimeout(()=>controller.abort(),12000)
 try{return await request<T>(path,{signal:controller.signal,silent})}catch(error){if(controller.signal.aborted&&!disposed)throw new Error(t('team.refreshTimeout'));throw error}finally{clearTimeout(timeout);readControllers.delete(controller)}
}
let stateSerial=0
async function load(force=false,background=false){if(loading.value && !force)return;const serial=++stateSerial;loading.value=true;try{const result=await boundedGet(root+'/state',background);if(!disposed && serial===stateSerial){state.value=result;updateGroupNotifications((result as any).groups || [],(result as any).notifications);if(!initialAddressLoaded){publicTarget.value=(result as any).preferences?.group_target || (result as any).groups?.[0]?.public_target || suggestedReachable((result as any).preferences?.local_addresses,(result as any).identity?.product==='win'?5588:Number(location.port||(location.protocol==='https:'?443:80)));initialAddressLoaded=true}}}catch(e){if(!disposed && serial===stateSerial)error.value=(e as Error).message}finally{if(serial===stateSerial)loading.value=false}}
async function deleteGroup(){
 if(busy.value || !deleteTarget.value)return
 working.value=true;deleteError.value='';const row=deleteTarget.value,gid=row.group_id || row._id
 try{const result=await post((row.group_id?'/links/':'/groups/')+encodeURIComponent(row._id)+'/delete',{confirmed:true});++stateSerial;state.value={groups:state.value.groups.filter((g:any)=>g._id!==row._id),links:state.value.links.filter((g:any)=>g._id!==row._id)}
  if(workspace.value?.group._id===gid){epoch++;workspaceSerial++;workspace.value=null;entries.value=[];draft.value='';attachments.value=[];peerId.value='';cursor=undefined;hasOlder.value=false;newMessages.value=0;dialog.value='';newKey.value='';previewData.value=null;restoreItem.value=null;providers.value=[];candidates.value={};for(const key of drafts.keys())if(key.startsWith(gid+':')){drafts.delete(key);pending.delete(key);attachmentDrafts.delete(key)}}
  for(const key of attachmentDrafts.keys())if(key.startsWith(gid+':'))attachmentDrafts.delete(key)
  deleteTarget.value=null;if(row.group_id && result.peer_notified===false)error.value=t('team.deleteOffline');await load(true)
 }catch(e){if(!disposed)deleteError.value=(e as Error).message}finally{working.value=false}
}
async function action(fn:()=>Promise<unknown>,modal=false){if(busy.value)return;working.value=true;if(modal)dialogError.value='';else error.value='';try{await fn();await load(true)}catch(e){if(!disposed){if(modal)dialogError.value=localizedError(e);else error.value=localizedError(e)}}finally{working.value=false}}
const invitationBody=(forever:boolean,expiry:number|null,single_use=false)=>({single_use,expires_in:forever?0:seconds(expiry),public_target:invitationTarget(publicTarget.value),max_members:maxMembers.value,approval_required:approvalRequired.value})
const create=()=>action(async()=>{const r=await post('/groups',{name:name.value,...invitationBody(longKey.value,minutes.value,createSingle.value),member_expires_in:seconds(memberMinutes.value)});publicTarget.value=r.public_target;dialog.value='';newKey.value=r.key},true)
const join=()=>action(async()=>{const r=await post('/join',{target:target.value,key:inviteKey.value,node_descriptor:nodeDescriptor.value});waitingLink=r._id;inviteKey.value='';invitationInput.value='';dialog.value='';message.info(t(r.state==='approved'?'invitationLink.joinApproved':'invitationLink.waitingApproval'))},true)
const refreshLink=(id:string)=>action(()=>post('/links/'+id+'/refresh'))
async function updateWorkspace(id:string,background=false){const serial=++workspaceSerial,e=epoch;const result=await boundedGet<any>(root+'/groups/'+id+'/workspace',background);if(!disposed && e===epoch && serial===workspaceSerial){workspace.value=result;lastWorkspace=Date.now()}}
async function open(id:string){if(busy.value)return;drafts.set(roomKey(),draft.value);saveAttachmentDrafts();epoch++;workspaceSerial++;workspace.value=null;peerId.value='';entries.value=[];attachments.value=[];dialog.value='';previewData.value=null;restoreItem.value=null;restoreError.value='';error.value='';const e=epoch;try{await updateWorkspace(id);if(disposed || e!==epoch)return;draft.value=drafts.get(roomKey()) || '';attachments.value=attachmentDrafts.get(roomKey()) || [];const options=await request<any>('/api/ai_config/options');if(e!==epoch || disposed)return;providers.value=options.items || [];await readRoom(true)}catch(exc){if(e===epoch && !disposed)error.value=(exc as Error).message}}
function leaveWorkspace(){if(busy.value)return;drafts.set(roomKey(),draft.value);saveAttachmentDrafts();epoch++;workspaceSerial++;workspace.value=null;entries.value=[];attachments.value=[];peerId.value='';cursor=undefined;cacheOpen.value=false;cacheGroup.value='';dialog.value='';previewData.value=null;restoreItem.value=null;void load(true)}
function showRename(id:string){renameId.value=id;renameName.value=(workspace.value?.members || []).find((m:any)=>m._id===id)?.name || '';showDialog('rename')}
const submitRename=()=>action(async()=>{const gid=workspace.value.group._id;await post('/groups/'+gid+(host.value?'/members/'+renameId.value+'/rename':'/rename-request'),{name:renameName.value});dialog.value='';await updateWorkspace(gid)},true)
const offerService=()=>action(async()=>{await post('/groups/'+workspace.value.group._id+'/service-offer',{enabled:serviceEnabled.value,public_target:serviceAddress.value});dialog.value='';await updateWorkspace(workspace.value.group._id)},true)
const assignService=(id:string,accepted:boolean)=>action(async()=>{await post('/groups/'+workspace.value.group._id+'/members/'+id+'/service-role',{accepted,priority:50});await updateWorkspace(workspace.value.group._id)},true)
const decideRename=(id:string,accepted:boolean)=>action(async()=>{const gid=workspace.value.group._id;await post('/groups/'+gid+'/members/'+id+'/rename-decision',{accepted});await updateWorkspace(gid)},true)
async function markVisibleRead(){if(!workspace.value || cursor===undefined || document.hidden || !follow || dialog.value || cacheOpen.value || previewData.value)return;const gid=workspace.value.group._id,e=epoch,key=roomKey(),position=cursor,claim=key+':'+position;if((readPositions.get(key)??-1)>=position||readPending.has(claim))return;readPending.add(claim);try{const result=await request<any>(root+'/groups/'+gid+'/read',{method:'POST',body:JSON.stringify({...roomArgs(),cursor:position}),silent:true});if(e===epoch && !disposed){readPositions.set(key,Math.max(readPositions.get(key)??-1,position));updateTeamUnread(result)}}catch{/* Retry on a later poll; never invent a successful read. */}finally{readPending.delete(claim)}}
async function refreshAll(){await load();if(workspace.value){try{await updateWorkspace(workspace.value.group._id);await readRoom()}catch(e){error.value=(e as Error).message}}}
function chooseRoom(peer:string){if(peer===peerId.value || busy.value)return;drafts.set(roomKey(),draft.value);saveAttachmentDrafts();epoch++;peerId.value=peer;draft.value=drafts.get(roomKey()) || '';attachments.value=attachmentDrafts.get(roomKey()) || [];entries.value=[];cursor=undefined;hasOlder.value=false;previewData.value=null;restoreItem.value=null;restoreError.value='';canSend.value=!peer || contacts.value.find((m:any)=>m._id===peer)?.state==='approved';void readRoom(true)}
function checkFollow(){const box=timeline.value;if(box)follow=box.scrollHeight-box.scrollTop-box.clientHeight<60;if(follow){newMessages.value=0;void markVisibleRead()}}
async function jumpLatest(){follow=true;newMessages.value=0;await nextTick();if(timeline.value)timeline.value.scrollTop=timeline.value.scrollHeight;void markVisibleRead()}
async function readRoom(reset=false){if(!workspace.value || disposed || readingEpoch===epoch)return;const e=epoch,gid=workspace.value.group._id;readingEpoch=e;if(reset){cursor=undefined;oldest=0;gap.value=false;follow=true;newMessages.value=0;roomLoading.value=true;roomError.value=''}try{const params=new URLSearchParams(roomArgs());if(cursor!==undefined)params.set('cursor',String(cursor));const result=await boundedGet<any>(root+'/groups/'+gid+'/messages?'+params,!reset);if(e!==epoch || disposed)return;const ids=new Set(entries.value.map(i=>i._id)),added=result.entries.filter((i:any)=>!ids.has(i._id));if(result.reset){entries.value=result.entries;gap.value=true}else {const positions=new Map(entries.value.map((item,index)=>[item._id,index]));for(const item of result.entries){const index=positions.get(item._id);if(index!==undefined && JSON.stringify(entries.value[index])!==JSON.stringify(item))entries.value[index]=item;}entries.value.push(...added);}cursor=result.cursor;canSend.value=result.can_send;if(reset || result.reset){oldest=result.oldest;hasOlder.value=result.has_older}else if(!oldest && result.entries.length){oldest=result.oldest;hasOlder.value=result.has_older}roomError.value=result.delivery_warning || '';if(follow && (reset||result.reset||added.length))await jumpLatest();else if(follow)void markVisibleRead();else newMessages.value+=added.length}catch(exc){if(e===epoch && !disposed)roomError.value=(exc as Error).message}finally{if(e===epoch){roomLoading.value=false;readingEpoch=-1}}}
async function older(){if(!workspace.value || olderLoading.value)return;olderLoading.value=true;const e=epoch,gid=workspace.value.group._id,box=timeline.value,height=box?.scrollHeight || 0,offset=box?.scrollTop || 0;try{const params=new URLSearchParams({...roomArgs(),before:String(oldest)}),result=await boundedGet<any>(root+'/groups/'+gid+'/messages?'+params);if(e!==epoch || disposed)return;const ids=new Set(entries.value.map(i=>i._id));entries.value.unshift(...result.entries.filter((i:any)=>!ids.has(i._id)));oldest=result.oldest;hasOlder.value=result.has_older;await nextTick();if(box){box.scrollTop=offset+box.scrollHeight-height;checkFollow()}}catch(exc){if(e===epoch)roomError.value=(exc as Error).message}finally{olderLoading.value=false}}
async function sendMessage(){
 if(!workspace.value || busy.value || !canSend.value || (!draft.value.trim() && !attachments.value.length))return
 const e=epoch,gid=workspace.value.group._id,key=roomKey(),content=draft.value,args=roomArgs(),files=[...attachments.value]
 if(e!==epoch || disposed)return
 sending.value=true;roomError.value=''
 try{
  if(content.trim()){
   let attempt=pending.get(key);if(!attempt || attempt.text!==content){attempt={text:content,nonce:sendNonce()};pending.set(key,attempt)}
   await post('/groups/'+gid+'/messages',{...args,text:content,nonce:attempt.nonce});pending.delete(key);drafts.delete(key);if(e===epoch && !disposed)draft.value=''
  }
  for(let index=0;index<files.length;index++){
   fileProgress.value=t('teamFiles.progress',{index:index+1,total:files.length,name:files[index].file.name});await uploadAttachment(gid,args,files[index])
   const remaining=(attachmentDrafts.get(key) || []).filter(item=>item.nonce!==files[index].nonce)
   if(remaining.length)attachmentDrafts.set(key,remaining);else attachmentDrafts.delete(key)
   if(e===epoch && !disposed)attachments.value=remaining
  }
  if(e===epoch && !disposed)await readRoom()
 }catch(exc){if(e===epoch && !disposed)roomError.value=localizedError(exc)}finally{sending.value=false;fileProgress.value=''}
}
async function loadKeys(){if(!workspace.value)return;keysLoading.value=true;try{const result=await request<any>(root+'/groups/'+workspace.value.group._id+'/invitations');if(!disposed)invitationKeys.value=result.items || []}catch(exc){dialogError.value=localizedError(exc)}finally{keysLoading.value=false}}
async function openKeys(){if(busy.value)return;dialog.value='keys';dialogError.value='';await loadKeys()}
const viewKey=(row:any)=>action(async()=>{const result=await post('/groups/'+workspace.value.group._id+'/invitations/'+row._id+'/reveal');publicTarget.value=result.public_target || '';newKey.value=result.key},true)
const revokeKey=(row:any)=>action(async()=>{await post('/groups/'+workspace.value.group._id+'/invitations/'+row._id+'/revoke');await loadKeys()},true)
const renewInvite=()=>action(async()=>{const r=await post('/groups/'+workspace.value.group._id+'/invite',{...invitationBody(inviteLong.value,inviteMinutes.value,inviteSingle.value),name:inviteName.value});dialog.value='';newKey.value=r.key},true)
const decide=(id:string,accepted:boolean)=>action(async()=>{const gid=workspace.value.group._id;await post('/groups/'+gid+'/members/'+id+'/decide',{accepted});await updateWorkspace(gid)},true)
const remove=(id:string)=>action(async()=>{const gid=workspace.value.group._id;await post('/groups/'+gid+'/members/'+id+'/remove');await updateWorkspace(gid);await readRoom()},true)
const candidateOpen=ref(false),candidateKeyword=ref(''),candidatePage=ref(1),candidateRows=ref<any[]>([]),candidateTotal=ref(0),candidateLoading=ref(false),candidateError=ref(''),selectedObject=ref<any>(null)
