const savingData=ref(false),previewError=ref(''),savedData=ref(false)
let candidateSerial=0
const candidateColumns=computed(()=>[{title:t('control.name'),key:'title'},...(kind.value==='finding'?[{title:t('repair128.fields.severity'),key:'severity'}]:[]),{title:t('repair128.fields.target'),dataIndex:'target'},{title:kind.value==='session'?t('repair128.fields.status'):t('repair128.fields.session_id'),dataIndex:kind.value==='session'?'status':'session'},{title:t('repair128.fields.save_date'),dataIndex:'time'},{title:t('control.actions'),key:'select'}])
async function loadCandidates(){const serial=++candidateSerial;candidateLoading.value=true;candidateError.value='';try{const data=await request<any>(root+'/candidates?kind='+kind.value+'&page='+candidatePage.value+'&keyword='+encodeURIComponent(candidateKeyword.value));if(serial===candidateSerial&&!disposed){candidateRows.value=data.items;candidateTotal.value=data.total}}catch(e){if(serial===candidateSerial)candidateError.value=(e as Error).message}finally{if(serial===candidateSerial)candidateLoading.value=false}}
function openCandidates(){candidatePage.value=1;candidateKeyword.value='';candidateOpen.value=true;void loadCandidates()}
function selectCandidate(row:any){selectedObject.value={...row,kind:kind.value};objectId.value=row._id;candidateOpen.value=false}
async function saveData(){if(savingData.value||savedData.value||previewLoading.value||previewError.value||!previewData.value)return;savingData.value=true;previewError.value='';const e=epoch;try{await post('/groups/'+workspace.value.group._id+'/items/'+previewData.value.item._id+'/import');if(e===epoch&&!disposed){savedData.value=true;message.success(t('repair128.saved'))}}catch(exc){if(e===epoch)previewError.value=(exc as Error).message}finally{savingData.value=false}}
