const share=()=>action(async()=>{if(!objectId.value||selectedObject.value?.kind!==kind.value)throw new Error(t('team.selectObject'));const gid=workspace.value.group._id;if(!shareAttempt.value||shareAttempt.value.object!==objectId.value||shareAttempt.value.kind!==kind.value)shareAttempt.value={object:objectId.value,kind:kind.value,nonce:sendNonce()};await post('/groups/'+gid+'/share',{nonce:shareAttempt.value.nonce,kind:kind.value,object_id:objectId.value,title:selectedObject.value?.title || kind.value,...roomArgs()});dialog.value='';await updateWorkspace(gid);await readRoom()},true)
const previewLoading=ref(false)
let previewSerial=0
function closePreview(){++previewSerial;previewData.value=null;previewLoading.value=false;previewError.value=''}
async function preview(id:string){
 if(!workspace.value || previewLoading.value&&previewData.value?.item?._id===id)return
 const e=epoch,serial=++previewSerial,gid=workspace.value.group._id
 const item=entries.value.find(entry=>entry._id===id)||workspace.value.items?.find((entry:any)=>entry._id===id)
 if(!item)return
 previewData.value={item,preview:{}};previewLoading.value=true;previewError.value='';savedData.value=false
 const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000)
 try{const data=await request<any>(root+'/groups/'+gid+'/items/'+id+'/receive',{method:'POST',body:'{}',signal:controller.signal,silent:true});if(e===epoch && serial===previewSerial&&!disposed)previewData.value=data}
 catch(error){if(e===epoch&&serial===previewSerial&&!disposed)previewError.value=localizedError(error)}
 finally{clearTimeout(timeout);if(serial===previewSerial)previewLoading.value=false}
}
